<?php $page_title='User Management'; require_once __DIR__.'/../includes/header.php'; require_perm($pdo,'users','can_view'); $msg='';
$roles=$pdo->query("SELECT * FROM roles ORDER BY id")->fetchAll();
if(isset($_GET['delete']) && can($pdo,'users','can_delete') && isset($_GET['csrf']) && hash_equals($_SESSION['csrf_token']??'',$_GET['csrf'])){ if((int)$_GET['delete']!==$_SESSION['user_id']){ $pdo->prepare("DELETE FROM users WHERE id=?")->execute([(int)$_GET['delete']]); $msg='User deleted.'; } else $msg='Cannot delete yourself.'; }
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $name=clean($_POST['full_name']??''); $user=clean($_POST['username']??''); $email=clean($_POST['email']??''); $role=(int)$_POST['role_id']; $pass=$_POST['password']??''; $active=(int)($_POST['is_active']??1);
 if($name&&$user&&$email&&$pass){ try{ $pdo->prepare("INSERT INTO users(full_name,username,email,password,role_id,is_active) VALUES(?,?,?,?,?,?)")->execute([$name,$user,$email,password_hash($pass,PASSWORD_DEFAULT),$role,$active]); $msg='User created.'; audit_log($pdo,'Create User','users',"Created user $user"); }catch(Exception $e){ $msg='Error: '.e($e->getMessage()); } } else $msg='All fields required.'; }
$rows=$pdo->query("SELECT u.*, r.name as role_name FROM users u JOIN roles r ON r.id=u.role_id ORDER BY u.id DESC")->fetchAll();
?>
<?php if($msg): ?><div class="alert alert-info"><?= e($msg) ?></div><?php endif; ?>
<div class="row"><div class="col-md-4"><div class="card p-3"><h5>Add User</h5><form method="post"><?= csrf_field() ?><label class="form-label">Full Name</label><input name="full_name" class="form-control mb-2" required><label class="form-label">Username</label><input name="username" class="form-control mb-2" required><label class="form-label">Email</label><input type="email" name="email" class="form-control mb-2" required><label class="form-label">Password</label><input type="password" name="password" class="form-control mb-2" required><label class="form-label">Role</label><select name="role_id" class="form-select mb-2"><?php foreach($roles as $r): ?><option value="<?= $r['id'] ?>"><?= e($r['name']) ?></option><?php endforeach; ?></select><label class="form-label">Status</label><select name="is_active" class="form-select mb-2"><option value="1">Active</option><option value="0">Inactive</option></select><button class="btn btn-primary">Create User</button></form></div></div>
<div class="col-md-8"><div class="card p-3"><table class="table"><thead><tr><th>Name</th><th>Username</th><th>Email</th><th>Role</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['full_name']) ?></td><td><?= e($r['username']) ?></td><td><?= e($r['email']) ?></td><td><?= e($r['role_name']) ?></td><td><?= $r['is_active']?'Active':'Inactive' ?></td><td><?php if(can($pdo,'users','can_delete')): ?><a data-confirm href="?delete=<?= $r['id'] ?>&csrf=<?= e(csrf_token()) ?>" class="btn btn-sm btn-danger">Delete</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
<?php require_once __DIR__.'/../includes/footer.php'; ?>
